export function isForbiddenSemanticKey(value) {
    return FORBIDDEN_SEMANTIC_KEYS.has(value.trim().toLowerCase());
}
/** Own-property lookup that is safe for Record-like consumer objects. */
export function getOwn(record, key) {
    if (!record || !Object.prototype.hasOwnProperty.call(record, key))
        return undefined;
    return record[key];
}
